public class ListSerializerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.ArrayList<String> colors = new java.util.ArrayList<>(
                    java.util.List.of("red", "green", "blue"));
            byte[] bytes = ListSerializer.save(colors);
            check("save produces data", true, bytes != null && bytes.length > 0);
            java.util.ArrayList<String> loaded = ListSerializer.load(bytes);
            check("contents survive", "[red, green, blue]",
                    loaded == null ? "null" : loaded.toString());
            check("size survives", 3, loaded == null ? -1 : loaded.size());
            check("loaded list is a new object", true,
                    loaded != null && loaded != colors);

            java.util.ArrayList<String> empty = ListSerializer.load(
                    ListSerializer.save(new java.util.ArrayList<>()));
            check("empty list round trip", "[]",
                    empty == null ? "null" : empty.toString());

            java.util.ArrayList<String> tricky = new java.util.ArrayList<>(
                    java.util.List.of("", "a,b", "a"));
            java.util.ArrayList<String> trickyBack = ListSerializer.load(
                    ListSerializer.save(tricky));
            check("empty strings and duplicates survive", "[, a,b, a]",
                    trickyBack == null ? "null" : trickyBack.toString());
        } catch (Exception e) {
            check("round trip completes without exception", "none",
                    e.getClass().getSimpleName());
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

